local CellLuaPath = "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestroyConsumeFilter"
------------ define ------------

--- from: Assets/BundleResources/Prefabs/Action/ActionTeamDestoryDialog.prefab > name: AlignNode
---@class CommonFilter
---@field Env                           	CommonFilter                            
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field CellRoot                      	UnityEngine.RectTransform               
---@field Cell                          	UnityEngine.RectTransform               
---@field Toggle                        	UnityEngine.RectTransform               
local CommonFilter = Class("CommonFilter")

------------ lifeCycle ------------

function CommonFilter:__init()
    self:CleanProperties()
end

function CommonFilter:__delete()
    self:CleanProperties()
end

function CommonFilter:Awake()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self.behaviourAction = behaviourAction
    end
end

function CommonFilter:Start()
end

function CommonFilter:OnDestroy()
    if self.behaviourAction then
        self.behaviourAction.UpdateAction = nil
        self.behaviourAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
------------ lifeCycle ------------


function CommonFilter:CleanProperties()
    self.data = nil
    self.behaviourAction = nil
    self.cellListInit = nil
    self.selectIndex = nil
    self.callback = nil
end

function CommonFilter:Update()
    if Utils.TouchCount() > 0 then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local rectTrans = self.CellRoot
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(rectTrans, position, UIModule.RootCanvas.canvas.worldCamera)
            if not isInRect then
                ---不在区域中
                self:SetListShowState(false)
            end
        end
    end
end

--- 刷新界面
---@param data any
function CommonFilter:RefreshPanel(data, defaultSelectIndex)
    if isNull(data) or (table.count(data) == 0) then
        return
    end
    self.data = data
    -- print(table.dump(data, nil, 3))
    self.selectIndex = defaultSelectIndex or 1
    
    self:InitToggle(data[self.selectIndex])

    self:SetListShowState(false)
end

--- 初始化toggle按钮
---@param cellData any
function CommonFilter:InitToggle(cellData)
    KTool.SetActive(self.Toggle, true)
    local lt = CfUtils.GetLuaScr(self.Toggle.gameObject, CellLuaPath)
    lt:Refresh(cellData, -1)
    lt:SetClickCallback(Bind(self, self.OnToggleClicked))
end

--- 刷新toggle按钮的数据
---@param cellData any
function CommonFilter:RefreshToggle(cellData)
    local lt = CfUtils.GetLuaScr(self.Toggle.gameObject, CellLuaPath)
    lt:Refresh(cellData, -1)
end

function CommonFilter:OnToggleClicked()
    if not checkBool(self.cellListInit) then
        self.cellListInit = true
        self:RefreshCellList()
    end

    -- 设置cell的选中状态
    local count = #self.data
    for i = 1, count, 1 do
        local tf = self.CellRoot:Find("Cell"..i)
        local lt = CfUtils.GetLuaScr(tf.gameObject, CellLuaPath)
        lt:SetSelected(i == self.selectIndex)
    end

    -- 展开列表
    self:SetListShowState(true)
end

--- 刷新列表数据
function CommonFilter:RefreshCellList()
    local childCount = self.CellRoot.childCount
    for i = 0, childCount - 1, 1 do
        KTool.SetActive(self.CellRoot:GetChild(i), false)
    end

    for i, cellData in ipairs(self.data) do
        self:RefreshCell(cellData, i)
    end
end

--- 刷新列表cell数据
---@param cellData any
---@param index any
function CommonFilter:RefreshCell(cellData, index)
    local go = nil
    local tf = self.CellRoot:Find("Cell"..index)
    if isNotNull(tf) then
        go = tf.gameObject
    end
    if isNull(go) then
        go = KTool.Instantiate(self.CellRoot.gameObject, self.Cell.gameObject)
        go.name = "Cell"..index
    end
    KTool.SetActive(go, true)
    local lt = CfUtils.GetLuaScr(go, CellLuaPath)
    lt:Refresh(cellData, index)
    lt:SetClickCallback(Bind(self, self.OnCellClicked))
end

function CommonFilter:OnCellClicked(index)
    local data = self.data[index]
    -- 刷新toggle按钮的数据
    self:RefreshToggle(data)
    -- 关闭列表
    self:SetListShowState(false)

    self.selectIndex = index

    if isNotNull(self.callback) then
        self.callback(self.selectIndex)
    end
end

--- 设置列表的展开和折叠状态
---@param state any
function CommonFilter:SetListShowState(state)
    -- 关闭列表
    KTool.SetActive(self.CellRoot, state)
    -- 设置toggle箭头的方向
    local lt = CfUtils.GetLuaScr(self.Toggle.gameObject, CellLuaPath)
    lt:SetArrowDirection(state and 1 or 0)
end

function CommonFilter:SetOnValueChanged(callback)
    self.callback = callback
end

return CommonFilter